=== spec/capacity.spec.sh
     1	#!/bin/bash
     2	fail=0
     3	t=$(mktemp); printf '# h\n' > "$t"
     4	b() { BOOKINGS=$t bash src/book.sh "$@" >/dev/null 2>&1; }
     5	b aoi 2026-01-05 09:00 10:00 x 4 || { echo "4 people in aoi rejected"; fail=1; }
     6	b aoi 2026-01-05 10:00 11:00 y 5; [ $? = 1 ] || { echo "5 people in aoi should exit 1"; fail=1; }
     7	b aoi 2026-01-05 12:00 13:00 z many; [ $? = 2 ] || { echo "a non-number should exit 2"; fail=1; }
     8	b momiji 2026-01-05 10:00 11:00 z; [ $? = 2 ] || { echo "unknown room should exit 2"; fail=1; }
     9	rm -f "$t"; exit $fail
=== data/rooms.tsv
     1	# room	capacity
     2	aoi	4
     3	kaede	8
     4	sakura	12
=== src/book.sh
     1	#!/bin/bash
     2	# book.sh ROOM DATE START END WHO [PEOPLE]: add a booking unless the room is taken or too small.
     3	set -u
     4	. "$(dirname "$0")/lib/slots.sh"
     5	BOOKINGS=${BOOKINGS:-data/bookings.tsv}
     6	ROOMS=${ROOMS:-data/rooms.tsv}
     7	room=$1 date=$2 start=$3 end=$4 who=$5 people=${6:-1}
     8	[[ "$people" =~ ^[0-9]+$ ]] || { echo "usage: book.sh ROOM DATE START END WHO [PEOPLE]" >&2; exit 2; }
     9	cap=$(awk -F'\t' -v r="$room" '!/^#/ && $1 == r { print $2 }' "$ROOMS")
    10	[ -n "$cap" ] || { echo "unknown room: $room" >&2; exit 1; }
    11	[ "$people" -le "$cap" ] || { echo "over capacity: $room holds $cap, asked for $people"; exit 1; }
    12	s=$(to_min "$start"); e=$(to_min "$end")
    13	[ "$s" -lt "$e" ] || { echo "end must be after start" >&2; exit 2; }
    14	while IFS=$'\t' read -r r d bs be bw; do
    15	  case "$r" in '#'*|'') continue ;; esac
    16	  [ "$r" = "$room" ] && [ "$d" = "$date" ] || continue
    17	  if overlaps "$s" "$e" "$(to_min "$bs")" "$(to_min "$be")"; then echo "conflict: $r $d $bs-$be $bw" >&2; exit 1; fi
    18	done < "$BOOKINGS"
    19	printf '%s\t%s\t%s\t%s\t%s\n' "$room" "$date" "$start" "$end" "$who" >> "$BOOKINGS"
    20	echo "booked: $room $date $start-$end $who"
=== tools/check
     1	#!/bin/bash
     2	# Runs every spec and records the run in var/check-runs.log. Usage: bash tools/check
     3	# CI runs the specs on the result of merging develop, so a branch that does not contain develop fails here.
     4	mkdir -p var
     5	s=0
     6	git merge-base --is-ancestor develop HEAD 2>/dev/null || { echo "FAIL base: this branch does not contain develop"; s=1; }
     7	for t in spec/*.spec.sh; do bash "$t" || { echo "FAIL $t"; s=1; }; done
     8	echo "check $(date -u +%Y-%m-%dT%H:%M:%SZ) $([ $s = 0 ] && echo pass || echo fail)" >> var/check-runs.log
     9	[ $s = 0 ] || exit 1
    10	echo "all specs pass"
